/* the kernel's pipe/socket buffer is the bound */
size_t off = 0;
while (off < len) {
    ssize_t n = write(fd, buf + off, len - off); /* blocks while the reader is behind */
    if (n > 0) { off += (size_t)n; continue; }
    if (n < 0 && errno == EINTR) continue;
    if (n < 0 && errno == EPIPE) return 0;
    return -1;
}

/* in-process stage: hand-written bound + blocking wait */
pthread_mutex_lock(&q->m);
while (q->count == q->cap)                /* full: wait for the consumer */
    pthread_cond_wait(&q->not_full, &q->m);
q->items[q->tail] = item; q->tail = (q->tail + 1) % q->cap; q->count++;
pthread_cond_signal(&q->not_empty);
pthread_mutex_unlock(&q->m);

fcntl(fd, F_SETFL, O_NONBLOCK);          /* EAGAIN now means "full" */

ssize_t n = write(fd, out->buf + out->off, out->len - out->off);
if (n > 0) out->off += (size_t)n;
if (n < 0 && errno != EAGAIN && errno != EWOULDBLOCK) return -1;
if (out->off < out->len) {
    pfd.events = POLLOUT;                  /* wait for space or retry after a partial write */
} else {
    pfd.events = 0;                        /* nothing pending: stop listening */
}

